type ExplicitApproval = 'allowed-once' | 'rejected'

export interface ApprovalCommand {
  code: string
  outcome: ExplicitApproval
}

export function parseApprovalCommand(text: string): ApprovalCommand | 'invalid' | undefined {
  const trimmed = text.trim()
  if (!/^\/(?:approve|reject)(?:\s|$)/iu.test(trimmed)) return undefined
  const match = /^\/(approve|reject)\s+([0-9]{6})$/iu.exec(trimmed)
  if (match === null) {
    if (/^\/(?:approve|reject)\s+[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/iu.test(trimmed)) return undefined
    return 'invalid'
  }
  return { code: match[2] as string, outcome: match[1]?.toLowerCase() === 'approve' ? 'allowed-once' : 'rejected' }
}

export function parseUnambiguousApproval(text: string): ExplicitApproval | undefined {
  const normalized = text.trim().replace(/[。！!]+$/u, '').toLocaleLowerCase()
  if (/^(?:批准|同意|approve|allow)$/u.test(normalized)) return 'allowed-once'
  if (/^(?:拒绝|不批准|reject|deny)$/u.test(normalized)) return 'rejected'
  return undefined
}
