export const TESTED_DSH_RUNTIME_VERSIONS = ['0.1.5-rc.2', '0.2.1-alpha.1'] as const
export type TestedDshRuntimeVersion = typeof TESTED_DSH_RUNTIME_VERSIONS[number]

export interface DshSessionHeader { id?: string }
export interface DshSessionEvent { type: string; data?: Record<string, unknown>; [key: string]: unknown }
export interface DshInspectedSession { meta: DshSessionHeader; events: readonly DshSessionEvent[] }
export interface DshQuestionItem {
  id: string
  question: string
  header?: string
  detail?: string
  options?: Array<{ label: string; description?: string }>
  multiSelect?: boolean
}
export interface DshQuestionAnswer {
  answers: Array<{ id: string; selected: string[]; custom?: string }>
}
export interface DshPendingQuestion { callId: string; questions: readonly DshQuestionItem[]; state: 'open' | 'continued' }
export interface DshAgentLike { id?: string; session: unknown; ctx: unknown; [key: string]: unknown }
export interface DshQuestionRequest {
  questions: DshQuestionItem[]
  agent?: unknown
  signal?: AbortSignal
  wait?: { callId: string; timed?: boolean }
}

type RecordLike = Record<string, unknown>

export function getDshService<T = unknown>(ctx: unknown, name: string): T | undefined {
  if (!isRecord(ctx)) return undefined
  const direct = ctx[name]
  if (direct !== undefined) return direct as T
  const get = ctx.get
  if (typeof get === 'function') {
    try { return (get as (name: string) => T | undefined).call(ctx, name) } catch { return undefined }
  }
  return undefined
}

export function provideDshService(ctx: unknown, name: string, value: unknown): () => void {
  if (!isRecord(ctx)) throw new Error('dsh_context_unavailable')
  const root = isRecord(ctx.root) ? ctx.root : undefined
  const reflect = isRecord(ctx.reflect) ? ctx.reflect : undefined
  const rootReflect = root && isRecord(root.reflect) ? root.reflect : undefined
  const provider = reflect?.provide ?? ctx.provide ?? rootReflect?.provide
  if (typeof provider !== 'function') throw new Error('dsh_context_provider_unavailable')
  const owner = provider === reflect?.provide ? reflect : provider === rootReflect?.provide ? rootReflect : ctx
  const dispose = (provider as (name: string, value: unknown) => unknown).call(owner, name, value)
  return typeof dispose === 'function' ? dispose as () => void : () => undefined
}

export function dshAgentSessionIds(agent: unknown): string[] {
  if (!isRecord(agent)) return []
  const value = agent
  const session = isRecord(value.session) ? value.session : {}
  const header = isRecord(session.header) ? session.header : {}
  return [...new Set([value.id, value.sessionId, session.id, session.sessionId, header.id]
    .filter((item): item is string => typeof item === 'string' && item.length > 0))]
}

export function addAgentSystemPromptSection(agentContext: unknown, input: { name: string; order: number; text: string }): () => void {
  const service = getDshService<RecordLike>(agentContext, 'systemPrompt')
  if (!service || typeof service.section !== 'function') throw new Error('dsh_system_prompt_service_unavailable')
  const dispose = (service.section as (input: { name: string; order: number; text: string }) => unknown).call(service, input)
  return typeof dispose === 'function' ? dispose as () => void : () => undefined
}

export function sessionEvents<T = any>(agent: unknown): readonly T[] {
  if (!isRecord(agent) || !isRecord(agent.session)) return []
  const session = agent.session as RecordLike & { snapshotEvents?: () => readonly DshSessionEvent[]; events?: readonly DshSessionEvent[] }
  return (session.snapshotEvents?.() ?? session.events ?? []) as readonly T[]
}

export async function inspectSession(ctx: unknown, id: string): Promise<DshInspectedSession> {
  const persistence = getDshService<RecordLike>(ctx, 'sessionPersistence')
  if (!persistence) throw new Error('dsh_session_persistence_unavailable')
  if (typeof persistence.inspect === 'function') {
    const result = await (persistence.inspect as (id: string) => Promise<{ meta?: DshSessionHeader; header?: DshSessionHeader; events: readonly DshSessionEvent[] }>)(id)
    return { meta: result.meta ?? result.header ?? {}, events: result.events }
  }
  if (typeof persistence.open !== 'function') throw new Error('dsh_session_inspection_unavailable')
  const handle = await (persistence.open as (id: string, access: 'read') => Promise<{ header: DshSessionHeader; read(): Promise<{ events: readonly DshSessionEvent[] }>; close(): Promise<void> }>)(id, 'read')
  try {
    const result = await handle.read()
    return { meta: handle.header, events: result.events }
  } finally {
    await handle.close()
  }
}

export interface PresetApi {
  resolveSessionPreset?: (session: { header: DshSessionHeader; events: readonly DshSessionEvent[] }) => string | undefined
  agentPresetProjectionDefinition?: {
    init(header: DshSessionHeader): string | null
    apply(state: string | null, event: DshSessionEvent): string | null
  }
}

export function resolvePresetFromApi(session: { header: DshSessionHeader; events: readonly DshSessionEvent[] }, api: PresetApi): string | undefined {
  if (typeof api.resolveSessionPreset === 'function') return api.resolveSessionPreset(session)
  const projection = api.agentPresetProjectionDefinition
  if (!projection) throw new Error('dsh_session_preset_resolver_unavailable')
  let state = projection.init(session.header)
  for (const event of session.events) state = projection.apply(state, event)
  return state ?? undefined
}

export async function resolveSessionPreset(session: { header: DshSessionHeader; events: readonly DshSessionEvent[] }): Promise<string | undefined> {
  const packageName: string = '@deepseek-ai/dsh-agent-presets'
  const api = await import(packageName) as unknown as PresetApi
  return resolvePresetFromApi(session, api)
}

export function registerUserQuestionAnswerer(
  ctx: unknown,
  answerer: (request: DshQuestionRequest, next: () => Promise<DshQuestionAnswer>) => Promise<DshQuestionAnswer>,
): () => void {
  if (!isRecord(ctx) || typeof ctx.on !== 'function') throw new Error('dsh_question_event_api_unavailable')
  const disposer = (ctx.on as (event: string, handler: (...args: never[]) => unknown, options?: unknown) => unknown)
    .call(ctx, 'user-questions/request', answerer as (...args: never[]) => unknown, { prepend: true })
  if (typeof disposer === 'function') return disposer as () => void
  return () => undefined
}

export function pendingUserQuestions(agent: unknown): DshPendingQuestion[] {
  if (!isRecord(agent) || !isRecord(agent.session)) return []
  const projections = getDshService<RecordLike>(agent.ctx, 'sessionProjections')
  if (!projections || typeof projections.stateOf !== 'function') return []
  const view = (projections.stateOf as (session: unknown, projection: string) => unknown).call(projections, agent.session, 'userQuestions')
  if (!isRecord(view) || !isRecord(view.questions) || !Array.isArray(view.questions.active)) return []
  return (view.questions.active as unknown[]).filter((item): item is DshPendingQuestion =>
    isRecord(item) && typeof item.callId === 'string' && Array.isArray(item.questions) && item.state === 'continued')
}

export function answerContinuedQuestion(agent: unknown, callId: string, answer: DshQuestionAnswer): boolean {
  if (!isRecord(agent) || !isRecord(agent.ctx)) return false
  const service = getDshService<RecordLike>(agent.ctx, 'userQuestions')
  if (!service || typeof service.answer !== 'function') return false
  return Boolean((service.answer as (agent: unknown, callId: string, answer: DshQuestionAnswer) => boolean).call(service, agent, callId, answer))
}

export async function askUserQuestion(ctx: unknown, input: { agent: unknown; id: string; question: string; options: Array<{ label: string; description?: string }>; signal?: AbortSignal }): Promise<DshQuestionAnswer> {
  const service = getDshService<RecordLike>(ctx, 'userQuestions')
  if (!service || typeof service.ask !== 'function') throw new Error('dsh_user_questions_unavailable')
  return await (service.ask as (request: { questions: DshQuestionItem[]; agent: unknown; signal?: AbortSignal }) => Promise<DshQuestionAnswer>).call(service, {
    questions: [{ id: input.id, question: input.question, options: input.options }],
    agent: input.agent,
    ...(input.signal ? { signal: input.signal } : {}),
  })
}

export function runtimeCapabilities(ctx: unknown): { userQuestions: boolean; timedQuestions: boolean; answerContinuedQuestion: boolean; sessionProjections: boolean } {
  const questions = getDshService<RecordLike>(ctx, 'userQuestions')
  const projections = getDshService<RecordLike>(ctx, 'sessionProjections')
  return {
    userQuestions: Boolean(questions && typeof questions.ask === 'function'),
    timedQuestions: Boolean(questions && typeof questions.askTimed === 'function'),
    answerContinuedQuestion: Boolean(questions && typeof questions.answer === 'function'),
    sessionProjections: Boolean(projections && typeof projections.stateOf === 'function'),
  }
}

export function assertSupportedDshRuntime(version: string, ctx: unknown): TestedDshRuntimeVersion {
  if (!(TESTED_DSH_RUNTIME_VERSIONS as readonly string[]).includes(version)) throw new Error(`workhub_dsh_runtime_unsupported:${version || 'unknown'}`)
  const capabilities = runtimeCapabilities(ctx)
  if (!capabilities.userQuestions) throw new Error('workhub_dsh_user_questions_unavailable')
  if (version === '0.2.1-alpha.1' && (!capabilities.timedQuestions || !capabilities.answerContinuedQuestion || !capabilities.sessionProjections)) {
    throw new Error('workhub_dsh_timed_question_capabilities_missing')
  }
  return version as TestedDshRuntimeVersion
}

function isRecord(value: unknown): value is RecordLike {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}
